func:
// msg.payload is the raw file text, read by the preceding "file in" core
// node — no require('fs'). Same fix as the Oura Sync flow's equivalent
// node; see its comment for the full explanation of why require() never
// worked here in the first place (Function nodes are sandboxed, this
// isn't a version-drift issue).
let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=godaddy_pull,status=started value=1 ' + nowNs;
return msg;

msg.url = msg.secrets.godaddy_base_url + '/api/pull_manual_data.php?scope=since_last';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token };
return msg;

// Full response (msg.payload) has the SAME shape as a human-triggered
// WardStock export — see build_export_records() in db.php. Two things
// happen with it (PLAN.md §4):
//  1. Structured/numeric fields -> InfluxDB (correlation-friendly copy)
//  2. The FULL raw response -> archived to local disk (disaster-recovery
//     artifact, restorable via WardStock's existing import.php)
//
// Includes medications as of this fix — originally missing entirely,
// meaning HA had no backup of dosage history despite being meant as the
// disaster-recovery source of truth. api/pull_manual_data.php and
// import.php were both updated to match (see db.php's build_export_records()
// and import.php's new 'medication' record_type handling).
const data = msg.payload;
if (!data || !Array.isArray(data.records)) {
    msg.job_failed = true;
    msg.failure_code = 'godaddy_error_response';
    msg.failure_detail = 'response missing records array: ' + JSON.stringify(data).slice(0, 300);
    return [null, msg];
}

function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }
const lines = [];
const nowNs = Date.now() * 1000000;

data.records.forEach(r => {
    if (r.record_type === 'incident') {
        const ts = r.occurred_at ? new Date(r.occurred_at.replace(' ', 'T')).getTime() * 1000000 : nowNs;
        const parts = [];
        ['anxiety_intensity','duration_minutes','nitroglycerin_taken','related_medication_id'].forEach(f => {
            if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]);
        });
        ['chest_sensation','arm_sensation','shoulder_sensation','headache_sensation','shaking','stomach_sensation','flu_symptoms_sensation','lethargy_sensation'].forEach(f => {
            if (r[f]) parts.push(f + '="' + r[f] + '"');
        });
        if (parts.length) {
            lines.push('incidents,category=' + esc(r.category) + ' ' + parts.join(',') + ' ' + ts);
        }
    } else if (r.record_type === 'daily_log') {
        const ts = r.log_date ? new Date(r.log_date + 'T12:00:00').getTime() * 1000000 : nowNs;
        const parts = [];
        ['sleep_duration_hrs','sleep_efficiency','resting_hr','hrv','weight','steps',
         'exercise_minutes','standing_minutes','caffeine_servings','alcohol_drinks',
         'mood_rating','state_of_mind'].forEach(f => {
            if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]);
        });
        // Fulgrim Flux-engine pass (Aug 2026) — added for analysis #9
        // (medication adherence vs. incidents) and #16 (night-waking
        // context), PLAN.md §11. Neither was previously pushed to
        // InfluxDB at all. Number()-coerced explicitly rather than
        // folded into the forEach above — PDO's emulated prepares (this
        // project's db.php default) return MySQL TINYINT as a PHP
        // string, so a naive truthy check on the string "0" would be
        // wrong (non-empty strings are always truthy in JS).
        if (r.medications_all_taken !== null && r.medications_all_taken !== undefined) {
            parts.push('medications_all_taken=' + (Number(r.medications_all_taken) ? 1 : 0));
        }
        if (r.night_waking_notes) parts.push('night_waking_notes="' + esc(r.night_waking_notes) + '"');
        if (parts.length) lines.push('daily_log_manual,log_date=' + esc(r.log_date) + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'therapy_session') {
        const ts = r.session_date ? new Date(r.session_date.replace(' ', 'T')).getTime() * 1000000 : nowNs;
        const parts = [];
        ['mood_before','mood_after'].forEach(f => { if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]); });
        if (parts.length) lines.push('therapy_sessions,session_type=' + esc(r.session_type || 'individual') + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'medication') {
        // Timestamped at start_date (noon, to avoid timezone-boundary
        // ambiguity) — this is a dosage-era record, not a daily reading,
        // so the timestamp marks when this dosage began, not "now."
        const ts = r.start_date ? new Date(r.start_date + 'T12:00:00').getTime() * 1000000 : nowNs;
        const parts = ['frequency_days=' + (r.frequency_days || 1)];
        if (r.sort_order !== null && r.sort_order !== undefined) parts.push('sort_order=' + r.sort_order);
        parts.push('dosage="' + (r.dosage || '') + '"');
        parts.push('end_date="' + (r.end_date || '') + '"');
        parts.push('active=' + (r.end_date ? 'false' : 'true'));
        lines.push('medications,name=' + esc(r.name) + ',med_type=' + esc(r.med_type || 'scheduled') + ' ' + parts.join(',') + ' ' + ts);
    } else if (r.record_type === 'medication_dosage_history') {
        // Timestamped at changed_at (noon) — marks when the new dosage
        // began, same convention as the medication block above. Tagged by
        // medication_name (denormalized in the export, see db.php) rather
        // than medication_id, since ids aren't stable across a re-import.
        const ts = r.changed_at ? new Date(r.changed_at + 'T12:00:00').getTime() * 1000000 : nowNs;
        const parts = [];
        parts.push('old_dosage="' + (r.old_dosage || '') + '"');
        parts.push('new_dosage="' + (r.new_dosage || '') + '"');
        if (r.notes) parts.push('notes="' + esc(r.notes) + '"');
        lines.push('medication_dosage_history,medication_name=' + esc(r.medication_name || 'unknown') + ' ' + parts.join(',') + ' ' + ts);
    }
});

msg.influx_lines = lines;
msg.raw_archive_data = data;
msg.record_count = data.records.length;
return [msg, null];

if (!msg.influx_lines.length) {
    // Nothing structured this run (e.g. only free-text fields changed) —
    // skip the write, go straight to archiving.
    return [null, msg];
}
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_lines.join('\n');
return [msg, msg];

// Prepares the archive write — the actual write happens in the
// following "file" (write) core node, not via require('fs') here.
// createDir is enabled on that node, replacing the old fs.mkdirSync
// call, so the /share/lucius_archive folder gets created automatically
// if it doesn't exist yet.
msg.filename = '/share/lucius_archive/latest_manual_data.json';
msg.payload = JSON.stringify(msg.raw_archive_data, null, 2);
return msg;

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=godaddy_pull,status=success record_count=' + (msg.record_count||0) + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.ha_entities = [
    { entity_id: 'input_datetime.lucius_godaddy_last_success', value: new Date().toISOString() },
    { entity_id: 'input_boolean.lucius_godaddy_last_attempt_ok', value: 'on' },
    { entity_id: 'input_datetime.lucius_godaddy_last_attempt', value: new Date().toISOString() }
];
return msg;

const nowNs = Date.now() * 1000000;
const code = msg.failure_code || 'unknown_error';
const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
msg.influx_finish_point = 'sync_job_runs,job_name=godaddy_pull,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
msg.ha_entities = [
    { entity_id: 'input_boolean.lucius_godaddy_last_attempt_ok', value: 'off' },
    { entity_id: 'input_datetime.lucius_godaddy_last_attempt', value: new Date().toISOString() },
    { entity_id: 'input_text.lucius_godaddy_last_error', value: code + ': ' + (msg.failure_detail || '') }
];
node.warn('GoDaddy pull failed: ' + code + ' - ' + msg.failure_detail);
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

// Same fix as the Oura Sync flow — see its "Split entities for HA
// WebSocket node" comment for the full explanation. Builds proper
// service-call objects (domain/service/target/data) instead of raw
// entity_id/value pairs, since setting a helper entity is a service
// call, not a direct state write. Feeds an api-call-service ("action")
// node now, not the deprecated ha-entity node.
//
// FIX (Aug 2026): same schema fix as the Oura Sync flow — the newer
// "action" node reads everything from msg.payload = { action, target,
// data } instead of separate top-level domain/service/target/payload
// properties. See the Oura Sync flow's equivalent comment for the full
// explanation and the doc link.
function buildServiceCall(entity_id, value) {
    const domain = entity_id.split('.')[0];
    if (domain === 'input_boolean') {
        return { domain, service: value === 'on' ? 'turn_on' : 'turn_off', target: { entity_id }, data: {} };
    }
    if (domain === 'input_text') {
        return { domain, service: 'set_value', target: { entity_id }, data: { value: String(value) } };
    }
    if (domain === 'input_datetime') {
        return { domain, service: 'set_datetime', target: { entity_id }, data: { datetime: value } };
    }
    node.warn('No known service mapping for entity domain: ' + domain);
    return null;
}
return (msg.ha_entities || []).map(e => {
    const call = buildServiceCall(e.entity_id, e.value);
    if (!call) return null;
    return { payload: { action: call.domain + '.' + call.service, target: call.target, data: call.data } };
}).filter(Boolean);
